/* @lc app=leetcode id=3630 lang=kotlin */ class Solution { fun maximizeXorAndXor(nums: IntArray): Long = nums.size.let { n -> (1 shl n).let { F -> IntArray(F).also { x -> (1 until F).forEach { m -> x[m] = x[m and (m - 1)] xor nums[Integer.numberOfTrailingZeros(m)] } }.let { xr -> IntArray(F).also { a -> (1 until F).forEach { m -> a[m] = if (m and (m - 1) == 0) nums[Integer.numberOfTrailingZeros(m)] else a[m and (m - 1)] and nums[Integer.numberOfTrailingZeros(m)] } }.let { an -> (0 until F).maxOf { b -> (xr[F - 1] xor xr[b]).let { T -> ((1 shl 30) - 1 xor T).let { mask -> IntArray(30).let { bs -> (0 until n).filter { b shr it and 1 == 0 }.forEach { i -> (29 downTo 0).fold(nums[i] and mask) { cur, bt -> if (cur shr bt and 1 == 0) cur else if (bs[bt] == 0) bs.set(bt, cur).let { 0 } else cur xor bs[bt] } }.let { (29 downTo 0).fold(0) { r, bt -> maxOf(r, r xor bs[bt]) }.let { mx -> (if (b == 0) 0L else an[b].toLong()) + T + 2L * mx } } } } } } } } } } }